cd /tmp && export STATE_DIR="$(mktemp -d)/state" && BOT=<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev2-haiku/work/ours-g4-2/bot.mjs && cat > /tmp/bot-selfcheck.mjs <<EOF
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { reserve, release } from '$BOT';
const run = promisify(execFile);
const H = 3600e3, M = 60e3;
const req = (userId, extra = {}) => ({ userId, maxPerWindow: 3, windowHours: 24, minGapMinutes: 0, ...extra });
const t0 = new Date('2026-10-23T10:00:00Z');
let fail = 0;
const ok = (c, msg) => { console.log(c ? 'PASS' : 'FAIL', msg); if (!c) fail++; };

// 1. in-process concurrency: 10 parallel reserves, cap 3
let r = await Promise.all(Array.from({ length: 10 }, () => reserve(req('lead_a'), t0)));
ok(r.filter(x => x.allowed).length === 3, 'in-process race: exactly 3 of 10 allowed');
ok(r.filter(x => !x.allowed).every(x => x.reason === 'window_limit_reached' && x.reservationId === null), 'denied shape + code');

// 2. cross-process race: 8 separate node processes, same lead, cap 3
const procs = Array.from({ length: 8 }, () => run(process.execPath, ['--input-type=module', '-e',
  `import{reserve}from'${'$BOT'}';const r=await reserve({userId:'lead_b',maxPerWindow:3,windowHours:24,minGapMinutes:0},new Date('2026-10-23T10:00:00Z'));console.log(JSON.stringify(r))`],
  { env: process.env }).then(o => JSON.parse(o.stdout)));
const pr = await Promise.all(procs);
ok(pr.filter(x => x.allowed).length === 3, 'cross-process race: exactly 3 of 8 allowed');
const ids = pr.filter(x => x.allowed).map(x => x.reservationId);

// 3. release from another process frees one slot; release is idempotent
await run(process.execPath, ['--input-type=module', '-e',
  `import{release}from'${'$BOT'}';await release('${ids[0]}');await release('${ids[0]}')`], { env: process.env });
r = await reserve(req('lead_b'), t0);
ok(r.allowed === true, 'slot freed by other process is reusable');
ok((await reserve(req('lead_b'), t0)).reason === 'window_limit_reached', 'cap holds again after reuse');

// 4. min gap
const g = { userId: 'lead_c', maxPerWindow: 10, windowHours: 24, minGapMinutes: 90 };
ok((await reserve(g, t0)).allowed, 'gap: first send allowed');
const near = await reserve(g, new Date(t0.getTime() + 89 * M));
ok(!near.allowed && near.reason === 'min_gap_not_elapsed', 'gap: 89 min refused with min_gap_not_elapsed');
ok((await reserve(g, new Date(t0.getTime() + 90 * M))).allowed, 'gap: exactly 90 min allowed');

// 5. window slides: sent at T, cap 1/24h, free again at T+24h exactly
const w = { userId: 'lead_d', maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 };
ok((await reserve(w, t0)).allowed, 'window: first allowed');
ok((await reserve(w, new Date(t0.getTime() + 24 * H - 1))).allowed === false, 'window: 1 ms before 24h still blocked');
ok((await reserve(w, new Date(t0.getTime() + 24 * H))).allowed, 'window: at exactly 24h free');

// 6. released slot in a later call does not count; unknown ids are no-ops
const rel = await reserve({ userId: 'lead_e', maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 }, t0);
await release(rel.reservationId);
await release('not-an-id'); await release(undefined);
ok((await reserve({ userId: 'lead_e', maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 }, t0)).allowed, 'release gives slot back');

// 7. input validation throws
let threw = false; try { await reserve({ userId: '', maxPerWindow: 1, windowHours: 1, minGapMinutes: 0 }, t0); } catch { threw = true; }
ok(threw, 'empty userId throws');

console.log(fail === 0 ? 'ALL PASS' : `${fail} FAILED`);
process.exit(fail ? 1 : 0);
EOF
